"use strict";(globalThis.webpackChunk_ai_autistic_intelligence_docusaurus_theme||=[]).push([[5236],{23982(e){e.exports=JSON.parse('{"version":{"pluginId":"ferrox-front","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"ferroxFrontSidebar":[{"type":"category","label":"\ud83d\ude80 Getting Started","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/overview","label":"Zero-JS Vision & Architecture","docId":"overview","unlisted":false},{"type":"link","href":"/docs/ferrox-front/overview/quickstart","label":"Quickstart Guide","docId":"overview/quickstart","unlisted":false},{"type":"link","href":"/docs/ferrox-front/architectures/architecture","label":"Core WebAssembly System Architecture","docId":"architectures/architecture","unlisted":false}],"collapsible":true},{"type":"category","label":"\ud83c\udfa8 Design System & Theming","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/design-system/tokens","label":"Design System Tokens & Aesthetics","docId":"design-system/tokens","unlisted":false},{"type":"link","href":"/docs/ferrox-front/design-system/theme-studio","label":"Theme Studio & Token Exporter","docId":"design-system/theme-studio","unlisted":false}],"collapsible":true},{"type":"category","label":"\ud83e\udde9 UI Component Library","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/components","label":"Enterprise UI Component Catalog","docId":"components","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components/buttons","label":"Buttons, Action Controls & Spinners","docId":"components/buttons","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components/form-controls","label":"Form Controls, Reactive Inputs & Validation","docId":"components/form-controls","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components/surfaces","label":"Surfaces, Cards, Badges & Alerts","docId":"components/surfaces","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components/overlays","label":"Overlays, Modals, DatePicker & Command Palette (\u2318K)","docId":"components/overlays","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components/icons","label":"Pure Rust 60+ SVG Vector Icon Engine","docId":"components/icons","unlisted":false}],"collapsible":true},{"type":"category","label":"\ud83d\udcca Data Visualization & Charts","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/charts","label":"SVG Vector Financial Charting Engine","docId":"charts","unlisted":false},{"type":"link","href":"/docs/ferrox-front/charts/chart-studio","label":"Nivo-Style Chart Studio & Playbook","docId":"charts/chart-studio","unlisted":false}],"collapsible":true},{"type":"category","label":"\u26a1 Enterprise Engines","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/datagrid","label":"Enterprise DataGrid (1M Rows & CSV Export)","docId":"datagrid","unlisted":false},{"type":"link","href":"/docs/ferrox-front/trading-desk","label":"Live Trading Desk (Interactive Wasm)","docId":"trading-desk","unlisted":false},{"type":"link","href":"/docs/ferrox-front/transports/ws","label":"Real-Time WebSockets Engine (ferrox-front-ws)","docId":"transports/ws","unlisted":false},{"type":"link","href":"/docs/ferrox-front/security/","label":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","docId":"security/security","unlisted":false}],"collapsible":true},{"type":"category","label":"\ud83c\udfdb\ufe0f Core Framework Architecture","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/fundamentals/core","label":"Core Kernel, Context Providers & Resource Managers","docId":"fundamentals/core","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/reactivity","label":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","docId":"fundamentals/reactivity","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/macros","label":"Procedural Macros, Component Annotations & Code Generation","docId":"fundamentals/macros","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/routing","label":"Client-Side Router, Route Guards & Lazy Loading","docId":"fundamentals/routing","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/templates","label":"Virtual DOM Templates, JSX Engine & HTML Macros","docId":"fundamentals/templates","unlisted":false}],"collapsible":true}]},"docs":{"architectures/architecture":{"id":"architectures/architecture","title":"Core WebAssembly System Architecture","description":"The ferrox-front architecture is designed around zero-cost abstractions, fine-grained reactive dependency graphs, single-threaded browser thread execution, WebAssembly linear memory layout, and WebGL rendering acceleration.","sidebar":"ferroxFrontSidebar"},"charts":{"id":"charts","title":"SVG Vector Financial Charting Engine","description":"ferrox-front-charts is an ultra-high-precision SVG vector graphics library engineered specifically for financial dashboards, trading desks, and quantitative telemetry, featuring zero JavaScript or Canvas dependencies.","sidebar":"ferroxFrontSidebar"},"charts/chart-studio":{"id":"charts/chart-studio","title":"Nivo-Style Chart Studio & Playbook","description":"Ferrox Front includes a high-performance vector charting engine inspired by Nivo, but engineered in 100% pure Rust WebAssembly with zero JavaScript charting dependencies.","sidebar":"ferroxFrontSidebar"},"components":{"id":"components","title":"Enterprise UI Component Catalog","description":"The ferrox-front-ui crate implements an enterprise-grade, strongly-typed Design System conforming to WCAG 2.1 AA accessibility guidelines. All components support rich visual variants, micro-animations, accessible :focus-visible focus rings, and glassmorphism styling.","sidebar":"ferroxFrontSidebar"},"components/buttons":{"id":"components/buttons","title":"Buttons, Action Controls & Spinners","description":"Ferrox Front delivers an accessible, high-performance button subsystem designed for rapid user interactions and sub-microsecond event dispatches in WebAssembly.","sidebar":"ferroxFrontSidebar"},"components/form-controls":{"id":"components/form-controls","title":"Form Controls, Reactive Inputs & Validation","description":"The Ferrox Front form subsystem achieves Zod and React Hook Form feature parity directly in Rust WebAssembly, eliminating the high CPU cost and memory allocations of JavaScript validation libraries.","sidebar":"ferroxFrontSidebar"},"components/icons":{"id":"components/icons","title":"Pure Rust 60+ SVG Vector Icon Engine","description":"Ferrox Front embeds a library of 60+ high-precision vector SVG icons compiled directly into Rust WebAssembly bytecode.","sidebar":"ferroxFrontSidebar"},"components/overlays":{"id":"components/overlays","title":"Overlays, Modals, DatePicker & Command Palette (\u2318K)","description":"Ferrox Front includes a suite of enterprise overlay components engineered directly in Rust WebAssembly, featuring Spotlight-style Command Palette (Cmd+K), pure vector SVG DatePicker, slide-over drawers, and WCAG 2.1 AA accessible focus-trapped modal dialogs.","sidebar":"ferroxFrontSidebar"},"components/surfaces":{"id":"components/surfaces","title":"Surfaces, Cards, Badges & Alerts","description":"Ferrox Front surfaces are built using hardware-accelerated frosted glass (backdrop-filter) and high-contrast semantic indicators that provide clear feedback during high-velocity trading and data analytics.","sidebar":"ferroxFrontSidebar"},"datagrid":{"id":"datagrid","title":"Enterprise DataGrid (1M Rows & CSV Export)","description":"The EnterpriseDataGrid component in Ferrox Front is engineered to exceed the capabilities of heavy JavaScript table frameworks like AG-Grid Enterprise and TanStack Table, guaranteeing zero garbage collection pauses even across datasets exceeding 1,000,000 records.","sidebar":"ferroxFrontSidebar"},"design-system/theme-studio":{"id":"design-system/theme-studio","title":"Theme Studio & Token Exporter","description":"The Theme Studio is an interactive design workbench compiled directly into WebAssembly. It allows engineering teams and designers to customize brand palettes, corner radiuses, and glassmorphism blurs on the fly, observe instant component previews, and export production-ready tokens in CSS and Rust formats.","sidebar":"ferroxFrontSidebar"},"design-system/tokens":{"id":"design-system/tokens","title":"Design System Tokens & Aesthetics","description":"Ferrox Front incorporates an enterprise-grade, high-contrast Design System engineered for institutional trading terminals, mission-critical dashboards, and high-frequency analytical applications.","sidebar":"ferroxFrontSidebar"},"fundamentals/core":{"id":"fundamentals/core","title":"Core Kernel, Context Providers & Resource Managers","description":"The ferrox-front-core crate is the foundation kernel of the Ferrox WebAssembly frontend framework. It manages component context providers (providecontext, usecontext), async resource loaders (create_resource), effect batch schedulers, and browser lifecycle event hooks.","sidebar":"ferroxFrontSidebar"},"fundamentals/macros":{"id":"fundamentals/macros","title":"Procedural Macros, Component Annotations & Code Generation","description":"The ferrox-front-macro crate provides Rust procedural macros (#[component], view!, derive(Store)) that transform declarative UI components and reactive state structs into optimized WebAssembly execution code.","sidebar":"ferroxFrontSidebar"},"fundamentals/reactivity":{"id":"fundamentals/reactivity","title":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","description":"The ferrox-front-core reactivity engine provides fine-grained reactive state management in WebAssembly. Built on push-pull signal graphs, it exposes Signal, ReadSignal, WriteSignal, Memo, and Effect primitives without relying on Virtual DOM diffing.","sidebar":"ferroxFrontSidebar"},"fundamentals/routing":{"id":"fundamentals/routing","title":"Client-Side Router, Route Guards & Lazy Loading","description":"The ferrox-front-router crate delivers client-side SPA navigation for WebAssembly apps. It features HTML5 History API integration, route path parameter matching, nested layout outlets, route protection guards, and code-split WebAssembly module lazy loading.","sidebar":"ferroxFrontSidebar"},"fundamentals/templates":{"id":"fundamentals/templates","title":"Virtual DOM Templates, JSX Engine & HTML Macros","description":"The ferrox-front-templates crate delivers zero-allocation HTML templating, WebAssembly compile-time JSX expansion, reactive DOM element patching, and SSR (Server-Side Rendering) string interpolation for Rust web applications.","sidebar":"ferroxFrontSidebar"},"overview":{"id":"overview","title":"Zero-JS Vision & Architecture","description":"Ferrox Front is a next-generation enterprise frontend framework and Design System written entirely in Rust WebAssembly (wasm32-unknown-unknown), specifically engineered to eliminate JavaScript, React, and npm bundlers from mission-critical web applications and high-frequency financial platforms.","sidebar":"ferroxFrontSidebar"},"overview/intro":{"id":"overview/intro","title":"Introduction & Ferrox-Front Architecture","description":"Welcome to Ferrox-Front, the high-performance WebAssembly (Wasm) frontend framework written in pure Rust. It combines fine-grained reactive signals, compile-time JSX HTML templates, zero-trust cryptographic security, real-time WebSocket state synchronization, and GPU-accelerated WebGL charts into a unified application suite."},"overview/quickstart":{"id":"overview/quickstart","title":"Quickstart Guide","description":"This guide demonstrates how to install prerequisites, build your first WebAssembly application in Rust using Ferrox Front, and run it in the browser.","sidebar":"ferroxFrontSidebar"},"security/security":{"id":"security/security","title":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","description":"The ferrox-front-security crate delivers zero-trust security for Rust WebAssembly applications. It features browser WebCrypto API bindings (AES-256-GCM, RSA-OAEP, ECDSA), zero-copy linear memory wiping (Zeroize), secure storage adapters, and HTML XSS sanitizers.","sidebar":"ferroxFrontSidebar"},"trading-desk":{"id":"trading-desk","title":"Live Trading Desk (Interactive Wasm)","description":"This page hosts the enterprise reference application Ferrox Live Trading Desk, compiled for target wasm32-unknown-unknown and executing natively inside your web browser.","sidebar":"ferroxFrontSidebar"},"transports/ws":{"id":"transports/ws","title":"Real-Time WebSockets Engine (ferrox-front-ws)","description":"ferrox-front-ws provides an asynchronous WebAssembly WebSocket client engine built natively for Rust frontends. It bridges browser WebSocket APIs (web_sys::WebSocket) with Ferrox Front\'s reactive Signals graph (Signal), enabling low-latency, real-time bi-directional streaming for dashboards, chat applications, financial tickers, and live notification systems.","sidebar":"ferroxFrontSidebar"},"ui/components":{"id":"ui/components","title":"Component Library & Interactive Playground","description":"Explore and interact with the Ferrox Front component library live in your browser using our Nivo-Style Interactive Playground."},"ui/ui-components":{"id":"ui/ui-components","title":"Glassmorphism Design System (ferrox-front-ui)","description":"ferrox-front-ui provides a complete, enterprise-grade Glassmorphism Design System for WebAssembly applications. It includes Design Tokens, a 12-column responsive layout grid, a Virtualized DataGrid (1,000,000+ rows), and a comprehensive library of pre-styled UI components."}}}}')}}]);